function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
    window.aivicNotify?.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify?.success(message);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    // 業務ロジックでの期間バリデーション
    if (validateComparisonPeriod && startDate && endDate) {
      try {
        const isValid = validateComparisonPeriod(startDate, endDate);
        if (!isValid) {
          showError('指定された期間は無効です');
          return false;
        }
      } catch (error) {
        showError('期間バリデーションエラー: ' + error.message);
        return false;
      }
    }

    return true;
  }

  // 需要予測データを取得・分析
  async function getDemandForecast(productId, storeId, startDate, endDate) {
    try {
      // 売上データを収集
      const salesData = collectSalesData ? await collectSalesData(productId, storeId, startDate, endDate) : [];

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : salesData;

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData ? filterValidProductData(productSalesData) : productSalesData;

      // 天候データを収集
      const weatherData = collectWeatherData ? await collectWeatherData(startDate, endDate) : [];

      // イベントデータを収集
      const eventData = collectEventData ? await collectEventData(startDate, endDate) : [];

      // 季節データを収集
      const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

      // 相関分析
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(validProductData, weatherData);
      }
      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(validProductData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlationResults.seasonal = analyzeCorrelationSalesSeason(validProductData, seasonalData);
      }

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData ? 
        await compareWithHistoricalData(validProductData, startDate, endDate) : null;

      return {
        salesData: validProductData,
        weatherData,
        eventData,
        seasonalData,
        correlationResults,
        historicalComparison
      };
    } catch (error) {
      showError('需要予測データの取得に失敗しました: ' + error.message);
      return null;
    }
  }

  // 需要予測結果をテーブルに表示
  function displayForecastResults(forecastData) {
    const tbody = container.querySelector('#forecast-results tbody');
    if (!tbody || !forecastData) return;

    tbody.innerHTML = '';

    if (forecastData.salesData && Array.isArray(forecastData.salesData)) {
      forecastData.salesData.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${item.productId || ''}</td>
          <td>${item.productName || ''}</td>
          <td>${item.predictedDemand || 0}</td>
          <td>${item.confidence || 0}%</td>
          <td>${item.recommendedOrder || 0}</td>
          <td>
            <button class="btn btn-sm btn-primary select-order" data-product-id="${item.productId}">
              選択
            </button>
          </td>
        `;
        tbody.appendChild(row);
      });
    }

    // 選択ボタンのイベントハンドラを追加
    tbody.querySelectorAll('.select-order').forEach(btn => {
      btn.addEventListener('click', handleSelectOrder);
    });
  }

  // 発注選択処理
  function handleSelectOrder(event) {
    const productId = event.target.dataset.productId;
    const row = event.target.closest('tr');
    const cells = row.querySelectorAll('td');

    const orderData = {
      productId: productId,
      productName: cells[1].textContent,
      predictedDemand: parseInt(cells[2].textContent) || 0,
      confidence: parseFloat(cells[3].textContent) || 0,
      recommendedOrder: parseInt(cells[4].textContent) || 0
    };

    // 既に選択済みかチェック
    const existingIndex = selectedOrders.findIndex(order => order.productId === productId);
    if (existingIndex >= 0) {
      selectedOrders[existingIndex] = orderData;
    } else {
      selectedOrders.push(orderData);
    }

    updateSelectedOrdersTable();
    showSuccess('発注候補に追加しました');
  }

  // 選択済み発注テーブルを更新
  function updateSelectedOrdersTable() {
    const tbody = container.querySelector('#selected-orders tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    selectedOrders.forEach((order, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${order.productName}</td>
        <td>
          <input type="number" class="form-control order-quantity" 
                 value="${order.recommendedOrder}" min="0" 
                 data-index="${index}">
        </td>
        <td>${order.confidence}%</td>
        <td>
          <button class="btn btn-sm btn-danger remove-order" data-index="${index}">
            削除
          </button>
        </td>
      `;
      tbody.appendChild(row);
    });

    // 数量変更のイベントハンドラ
    tbody.querySelectorAll('.order-quantity').forEach(input => {
      input.addEventListener('change', (e) => {
        const index = parseInt(e.target.dataset.index);
        selectedOrders[index].orderQuantity = parseInt(e.target.value) || 0;
      });
    });

    // 削除ボタンのイベントハンドラ
    tbody.querySelectorAll('.remove-order').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const index = parseInt(e.target.dataset.index);
        selectedOrders.splice(index, 1);
        updateSelectedOrdersTable();
        showSuccess('発注候補から削除しました');
      });
    });
  }

  // 需要予測実行
  async function executeForecast() {
    if (!validateDateRange()) return;

    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;
    const storeId = container.querySelector('#store-select')?.value;
    const productId = container.querySelector('#product-select')?.value;

    if (!startDate || !endDate) {
      showError('開始日と終了日を入力してください');
      return;
    }

    const loadingDiv = container.querySelector('#loading');
    if (loadingDiv) loadingDiv.classList.remove('hidden');

    try {
      const forecastData = await getDemandForecast(productId, storeId, startDate, endDate);
      displayForecastResults(forecastData);

      const resultsDiv = container.querySelector('#forecast-results');
      if (resultsDiv) resultsDiv.classList.remove('hidden');

      showSuccess('需要予測が完了しました');
    } catch (error) {
      showError('需要予測の実行に失敗しました: ' + error.message);
    } finally {
      if (loadingDiv) loadingDiv.classList.add('hidden');
    }
  }

  // 発注データ保存
  async function saveOrders() {
    if (selectedOrders.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    try {
      const orderData = selectedOrders.map(order => ({
        productId: order.productId,
        productName: order.productName,
        orderQuantity: order.orderQuantity || order.recommendedOrder,
        predictedDemand: order.predictedDemand,
        confidence: order.confidence,
        orderDate: new Date().toISOString().split('T')[0],
        status: '未発注'
      }));

      // 発注データを保存
      for (const order of orderData) {
        await window.aivicApi.save(tables[ORDER_TABLE], order);
      }

      showSuccess('発注データを保存しました');
      selectedOrders = [];
      updateSelectedOrdersTable();

      // 発注履歴を更新
      await loadOrderHistory();

    } catch (error) {
      showError('発注データの保存に失敗しました: ' + error.message);
    }
  }

  // 発注履歴を読み込み
  async function loadOrderHistory() {
    try {
      const orders = await window.aivicApi.list(tables[ORDER_TABLE]);
      const tbody = container.querySelector('#order-history tbody');
      if (!tbody) return;

      tbody.innerHTML = '';

      orders.forEach(order => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${order.orderDate || ''}</td>
          <td>${order.productName || ''}</td>
          <td>${order.orderQuantity || 0}</td>
          <td>${order.predictedDemand || 0}</td>
          <td>
            <span class="badge ${order.status === '完了' ? 'badge-success' : 'badge-warning'}">
              ${order.status || '未発注'}
            </span>
          </td>
          <td>
            ${order.status !== '完了' ? 
              `<button class="btn btn-sm btn-success complete-order" data-id="${order.id}">完了</button>` : 
              ''
            }
          </td>
        `;
        tbody.appendChild(row);
      });

      // 完了ボタンのイベントハンドラ
      tbody.querySelectorAll('.complete-order').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          const orderId = e.target.dataset.id;
          try {
            await window.aivicApi.update(tables[ORDER_TABLE], orderId, { status: '完了' });
            showSuccess('発注を完了しました');
            await loadOrderHistory();
          } catch (error) {
            showError('発注完了の更新に失敗しました: ' + error.message);
          }
        });
      });

    } catch (error) {
      showError('発注履歴の読み込みに失敗しました: ' + error.message);
    }
  }

  // 店舗・商品選択肢を読み込み
  async function loadSelectOptions() {
    try {
      // 店舗選択肢
      const stores = await window.aivicApi.list(tables[STORES_TABLE]);
      const storeSelect = container.querySelector('#store-select');
      if (storeSelect) {
        storeSelect.innerHTML = '<option value="">全店舗</option>';
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.name;
          storeSelect.appendChild(option);
        });
      }

      // 商品選択肢
      const products = await window.aivicApi.list(tables[PRODUCTS_TABLE]);
      const productSelect = container.querySelector('#product-select');
      if (productSelect) {
        productSelect.innerHTML = '<option value="">全商品</option>';
        products.forEach(product => {
          const option = document.createElement('option');
          option.value = product.id;
          option.textContent = product.name;
          productSelect.appendChild(option);
        });
      }

      currentProducts = products;

    } catch (error) {
      showError('選択肢の読み込みに失敗しました: ' + error.message);
    }
  }

  // イベントハンドラの設定
  function setupEventHandlers() {
    // 需要予測実行ボタン
    const forecastBtn = container.querySelector('#execute-forecast');
    if (forecastBtn) {
      forecastBtn.addEventListener('click', executeForecast);
    }

    // 発注保存ボタン
    const saveBtn = container.querySelector('#save-orders');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrders);
    }

    // 日付入力のバリデーション
    const dateInputs = container.querySelectorAll('#date-start, #date-end');
    dateInputs.forEach(input => {
      input.addEventListener('change', validateDateRange);
    });

    // 履歴更新ボタン
    const refreshBtn = container.querySelector('#refresh-history');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', loadOrderHistory);
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadSelectOptions();
      await loadOrderHistory();
      setupEventHandlers();

      // デフォルト日付設定
      const today = new Date();
      const startDate = new Date(today.getFullYear(), today.getMonth(), 1);
      const endDate = new Date(today.getFullYear(), today.getMonth() + 1, 0);

      const startInput = container.querySelector('#date-start');
      const endInput = container.querySelector('#date-end');

      if (startInput) startInput.value = startDate.toISOString().split('T')[0];
      if (endInput) endInput.value = endDate.toISOString().split('T')[0];

    } catch (error) {
      showError('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
